//! The browser API: one wasm module with a class per core, the assembler and
//! the disassembler.
//!
//! Every core class has the same common methods (generated by `core_api!`
//! from the `Core` trait): `name`, `pc`, `cycle`, `halted`, `priv_mode`,
//! `in_trap`, `pending_irq`, `reset`, `load`, `step`, `step_instr`, `run`,
//! `regs`, `poke_reg`, `regions`, `mem`, `poke_mem`, `csr_read`,
//! `csr_write`, `csr_snapshot`, `raise_irq(mask)`, `clear_irq`,
//! `last_trap`. Per-core extras sit beside them in the core's file.
//!
//! Build: `npm run wasm` (wasm-pack, `--target web`).
//!
//! ```js
//! import init, { Pipeline, assemble } from './wasm/cpu_sim.js'
//! await init()
//! const cpu = new Pipeline()
//! cpu.load(0, assemble('addi x1, x0, 7').instructions.map(i => i.value))
//! cpu.step_instr()
//! ```

use serde::Serialize;
use wasm_bindgen::prelude::*;

use crate::isa::csr::{csr_desc, csr_name};
use crate::isa::disasm::descriptions::mnemonic_desc;
use crate::sim::system::TrapInfo;

mod single;
mod pipeline;
mod barrel;
mod mempanel;
mod ooo;

pub use barrel::Barrel;
pub use mempanel::MemPanel;
pub use ooo::Ooo;
pub use pipeline::Pipeline;
pub use single::SingleCycle;

/// Any serialisable value to JS (null if it cannot be converted). `None`
/// becomes `null` (the generated types say `T | null`: `#[tsify(missing_as_null)]`).
pub(crate) fn js<T: Serialize + ?Sized>(v: &T) -> JsValue {
    v.serialize(&serde_wasm_bindgen::Serializer::new().serialize_missing_as_null(true))
        .unwrap_or(JsValue::NULL)
}

/// Assemble RV32I source (the editor panel): `{ success, instructions, errors }`.
#[wasm_bindgen(unchecked_return_type = "AssemblerResult")]
pub fn assemble(source: &str) -> JsValue { js(&rv_asm::assemble(source)) }

#[derive(Serialize, tsify::Tsify)]

#[tsify(missing_as_null)]
struct DisasmJson { class: &'static str, mnemonic: String, operands: String, desc: String }

/// Disassemble one 32-bit word: `{ class, mnemonic, operands, desc }`.
#[wasm_bindgen(unchecked_return_type = "DisasmJson")]
pub fn disasm(word: u32) -> JsValue {
    let d = crate::isa::disasm::disassemble(word);
    let desc = mnemonic_desc(&d.mnemonic).unwrap_or("").to_string();
    js(&DisasmJson { class: d.class, mnemonic: d.mnemonic, operands: d.operands, desc })
}

// ── Common method set ───────────────────────────────────────────────────────

/// `step_instr` gives up after this many steps (a stalled or spinning core).
pub(crate) const STEP_INSTR_MAX: u64 = 10_000;

#[derive(Serialize, tsify::Tsify)]

#[tsify(missing_as_null)]
pub(crate) struct BoundaryJson { pub retired: u32, pub halted: bool }

#[derive(Serialize, tsify::Tsify)]

#[tsify(missing_as_null)]
pub(crate) struct CsrEntryJson { pub addr: u16, pub name: String, pub value: u32, pub desc: String }

pub(crate) fn csr_entries(v: Vec<(u16, u32)>) -> Vec<CsrEntryJson> {
    v.into_iter().map(|(addr, value)| CsrEntryJson {
        addr,
        name: csr_name(addr).map(str::to_string).unwrap_or_else(|| format!("{addr:#05x}")),
        value,
        desc: csr_desc(addr).unwrap_or("").to_string(),
    }).collect()
}

#[derive(Serialize, tsify::Tsify)]

#[tsify(missing_as_null)]
pub(crate) struct TrapJson {
    pub cycle: u64, pub from: &'static str, pub to: &'static str,
    pub cause: u32, pub is_interrupt: bool, pub epc: u32, pub tval: u32,
}

pub(crate) fn trap_json(t: Option<TrapInfo>) -> JsValue {
    match t {
        Some(t) => js(&TrapJson {
            cycle: t.cycle, from: t.from_mode.as_str(), to: t.to_mode.as_str(),
            cause: t.cause, is_interrupt: t.is_interrupt, epc: t.epc, tval: t.tval,
        }),
        None => JsValue::NULL,
    }
}

/// The common methods, on a class whose `inner` field implements `Core`.
macro_rules! core_api {
    ($class:ident) => {
        #[wasm_bindgen]
        impl $class {
            /// Core kind: "single-cycle", "pipeline", "barrel", "out-of-order".
            #[wasm_bindgen(getter)] pub fn name(&self) -> String { Core::name(&self.inner).into() }
            #[wasm_bindgen(getter)] pub fn pc(&self) -> u32 { Core::pc(&self.inner) }
            /// Clocks completed (single-cycle: instructions).
            #[wasm_bindgen(getter)] pub fn cycle(&self) -> f64 { Core::cycle(&self.inner) as f64 }
            #[wasm_bindgen(getter)] pub fn halted(&self) -> bool { Core::halted(&self.inner) }
            /// "M", "S" or "U".
            #[wasm_bindgen(getter)] pub fn priv_mode(&self) -> String { Core::sys(&self.inner).priv_mode.as_str().into() }
            #[wasm_bindgen(getter)] pub fn in_trap(&self) -> bool { Core::sys(&self.inner).in_trap() }
            /// Interrupt lines raised from outside (mip bits).
            #[wasm_bindgen(getter)] pub fn pending_irq(&self) -> u32 { Core::sys(&self.inner).pending_irq }

            /// Core reset (registers, PC, pipeline); see the core for what memory keeps.
            pub fn reset(&mut self) { Core::reset(&mut self.inner) }
            /// Words into memory from byte address `base` (no timing).
            pub fn load(&mut self, base: u32, words: &[u32]) { Core::load(&mut self.inner, base, words) }
            /// The core's smallest step: `{ retired, halted }`.
            #[wasm_bindgen(unchecked_return_type = "BoundaryJson")]
            pub fn step(&mut self) -> JsValue {
                let b = Core::step(&mut self.inner);
                $crate::wasm::js(&$crate::wasm::BoundaryJson { retired: b.retired, halted: b.halted })
            }
            /// Step until an instruction completes. False if none did (halted / gave up).
            pub fn step_instr(&mut self) -> bool { Core::step_instr(&mut self.inner, $crate::wasm::STEP_INSTR_MAX) }
            /// Up to `steps` steps, stopping at a halt; instructions completed.
            pub fn run(&mut self, steps: u32) -> f64 { Core::run(&mut self.inner, steps as u64) as f64 }

            /// The 32 registers.
            pub fn regs(&self) -> Vec<u32> { Core::regs(&self.inner).to_vec() }
            /// Write register `i` (x0 stays 0).
            pub fn poke_reg(&mut self, i: u8, v: u32) { Core::poke_reg(&mut self.inner, i, v) }
            /// `[{ name, base, words }]`: the memory regions the panel shows.
            #[wasm_bindgen(unchecked_return_type = "Region[]")]
            pub fn regions(&self) -> JsValue { $crate::wasm::js(&Core::regions(&self.inner)) }
            /// `n` words from byte address `base`, as the program sees them (no side effects).
            pub fn mem(&self, base: u32, n: u32) -> Vec<u32> { $crate::sim::mem::Bus::peek_words(Core::bus(&self.inner), base, n) }
            /// Write one word at byte address `addr` (ROM included, no timing).
            pub fn poke_mem(&mut self, addr: u32, v: u32) { $crate::sim::mem::Bus::poke(Core::bus_mut(&mut self.inner), addr, v) }

            pub fn csr_read(&self, addr: u16) -> u32 { Core::csr_read(&self.inner, addr) }
            pub fn csr_write(&mut self, addr: u16, v: u32) { Core::csr_write(&mut self.inner, addr, v) }
            /// `[{ addr, name, value, desc }]` of the CSRs the core has.
            #[wasm_bindgen(unchecked_return_type = "CsrEntryJson[]")]
            pub fn csr_snapshot(&self) -> JsValue {
                $crate::wasm::js(&$crate::wasm::csr_entries(Core::csr_snapshot(&self.inner)))
            }
            /// Raise external interrupt lines (mip bit mask) until `clear_irq`.
            pub fn raise_irq(&mut self, mask: u32) { Core::raise_irq(&mut self.inner, mask) }
            pub fn clear_irq(&mut self) { Core::clear_irq(&mut self.inner) }
            /// `{ cycle, from, to, cause, is_interrupt, epc, tval }` of the last trap, or null.
            #[wasm_bindgen(unchecked_return_type = "TrapJson | null")]
            pub fn last_trap(&self) -> JsValue { $crate::wasm::trap_json(Core::last_trap(&self.inner)) }
        }
    };
}
pub(crate) use core_api;
